    return ""
}

02-basics.solution:
fn initials(first: String, last: String) -> String {
    let a = first.slice(0, 1).upper()
    let b = last.slice(0, 1).upper()
    return "{a}.{b}."
}

03-control.solution:
fn grade(score: Int) -> String {
    if score >= 90 {
        return "excellent"
    } else if score >= 70 {
        return "good"
    } else if score >= 50 {
        return "pass"
    }
    return "fail"
}

