03-control.solution:
fn sum_to(n: Int) -> Int {
    var total = 0
    for i in 1..=n {
        total += i
    }
    return total
}

fn fizzbuzz(n: Int) -> String {
    if n % 15 == 0 {
        return "FizzBuzz"
    } else if n % 3 == 0 {
        return "Fizz"
    } else if n % 5 == 0 {
        return "Buzz"
    }
    return to_string(n)
}

