}

05-types.starter:
type Student = { name: String, grade: Int }

fn best(students: List<Student>) -> String {
    return "nobody"
}

05-types.solution:
type Student = { name: String, grade: Int }

fn best(students: List<Student>) -> String {
    return match students.max_by(|s| s.grade) {
        Some(s) => s.name
        None => "nobody"
    }
}

