05-types.starter:
fn parse_percent(text: String) -> Result<Int, String> {
    return Err("not a number")
}

05-types.solution:
fn parse_percent(text: String) -> Result<Int, String> {
    return match text.parse_int() {
        Some(n) => match n >= 0 && n <= 100 {
            true => Ok(n)
            false => Err("out of range")
        }
        None => Err("not a number")
    }
}

